import { Button, RelativeTimeCard } from '@vercel/geistcn/components';
import type { JSX } from 'react';

// The card open on each side, as a hover from rest opens it.
export function Component(): JSX.Element {
  const date = new Date('2026-09-09T08:15:30Z').getTime();
  return (
    <div className="flex flex-row items-stretch justify-around flex-initial">
      <div className="flex flex-col items-center justify-center flex-initial">
        <RelativeTimeCard date={date} side="top">
          <Button>Hover Me</Button>
        </RelativeTimeCard>
      </div>
      <div className="flex flex-col items-center justify-center flex-initial">
        <RelativeTimeCard date={date} side="bottom">
          <Button>Hover Me</Button>
        </RelativeTimeCard>
      </div>
      <div className="flex flex-col items-center justify-center flex-initial">
        <RelativeTimeCard date={date} side="left">
          <Button>Hover Me</Button>
        </RelativeTimeCard>
      </div>
      <div className="flex flex-col items-center justify-center flex-initial">
        <RelativeTimeCard date={date} side="right">
          <Button>Hover Me</Button>
        </RelativeTimeCard>
      </div>
    </div>
  );
}

import { RelativeTimeCard } from '@vercel/geistcn/components';
import type { JSX } from 'react';

// No children: the component draws the short age itself.
export function Component(): JSX.Element {
  const date = new Date('2026-09-09T08:15:30Z').getTime();
  return <RelativeTimeCard date={date} />;
}
